char* process(int buf_size, const char* path) {
  char *buffer = malloc(buf_size);
  if (!buffer) return NULL;

  size_t pathlen = strlen(path);
  if (pathlen >= (size_t)buf_size) {
      free(buffer);
      return NULL;
  }

  // Copies pathlen characters plus the null terminator
  memcpy(buffer, path, pathlen + 1);
  return buffer;
}

char* process(STRUCT *a) {
  for (int i = 0; i <= a->argc; i++) {
      if (a->argv[i] == 'B') {
          return a->argv[i];
      }
  }
  return NULL;
}
